function c(){const e=document.getElementById("nav-toggle"),d=document.querySelector(".nav-toggle-label");if(!e||!d)return;const t=()=>{d.setAttribute("aria-expanded",e.checked?"true":"false")};t(),e.addEventListener("change",t),document.addEventListener("keydown",n=>{n.key==="Escape"&&e.checked&&(e.checked=!1,t())}),document.addEventListener("click",n=>{!n.target.closest(".site-header")&&e.checked&&(e.checked=!1,t())})}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",c):c();
